def minSessions(tasks, sessionTime):
    tasks.sort(reverse=True)
    sessions = [0] * len(tasks)
    def dfs(i, session):
        if i == len(tasks):
            return 1 if session == 0 else float('inf')
        if sessions[i] != 0:
            return dfs(i + 1, session)
        sessions[i] = 1
        res = dfs(i + 1, session - 1) + 1
        sessions[i] = 0
        return min(res, dfs(i + 1, session))
    return dfs(0, sessionTime)

